import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.vLhlLNVn.js";const c=JSON.parse('{"title":"Wie wähle ich Version und Zugriffsweg des Dashboards?","description":"","frontmatter":{"order":3,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/02.anleitungen/03.dashboard-nutzen.md"},"headers":[],"relativePath":"de/adapter/esphome/anleitungen/dashboard-nutzen.md","filePath":"de/adapter/esphome/anleitungen/dashboard-nutzen.md","lastUpdated":1795571670000}'),s={name:"de/adapter/esphome/anleitungen/dashboard-nutzen.md"};function d(n,e,o,h,l,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="wie-wahle-ich-version-und-zugriffsweg-des-dashboards" tabindex="-1">Wie wähle ich Version und Zugriffsweg des Dashboards? <a class="header-anchor" href="#wie-wahle-ich-version-und-zugriffsweg-des-dashboards" aria-label="Permalink to &quot;Wie wähle ich Version und Zugriffsweg des Dashboards?&quot;">​</a></h1><p><a id="choose-update-esphome-dashboard-version"></a></p><h2 id="wie-wahle-oder-aktualisiere-ich-die-esphome-dashboard-version-auch-altere" tabindex="-1">Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version, auch ältere? <a class="header-anchor" href="#wie-wahle-oder-aktualisiere-ich-die-esphome-dashboard-version-auch-altere" aria-label="Permalink to &quot;Wie wähle oder aktualisiere ich die ESPHome-Dashboard-Version, auch ältere?&quot;">​</a></h2><p>Du wählst die Version in den Instanz-Einstellungen unter „ESPHome Dashboard-Version“ oder tippst sie dort ein. Nach dem Speichern startet die Instanz neu und installiert genau diese Version. Voreingestellt ist <code>2026.6.5</code>.</p><p>Alles, was ESPHome sonst noch braucht, sucht der Adapter passend aus. Ab ESPHome 2026.7.0 installiert er zusätzlich ESPHome Device Builder, das dort das Dashboard bereitstellt. Pillow bringt ESPHome selbst in der passenden Version mit.</p><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne die Instanz-Einstellungen, Reiter „ESPHome-Dashboard“.</li><li>Wähle bei „ESPHome Dashboard-Version“ eine Version aus der Liste. Fehlt sie dort, etwa eine ältere oder eine Beta, tipp sie ein, z. B. <code>2026.5.3</code>.</li><li>Speichere. Die Instanz startet neu und installiert die Version. Das dauert einige Minuten, der ESPHome-Tab zeigt solange das Startprotokoll.</li><li>Im Log steht danach „Starting ESPHome Dashboard. ESPHome version: …“ mit den installierten Versionen von ESPHome, Pillow und Device Builder.</li></ol><p>Die Liste kommt beim Start der Instanz von GitHub und enthält die rund 30 neuesten Releases. Ist GitHub nicht erreichbar, nimmt der Adapter die Liste vom letzten Abruf. <code>esphome.0._ESPHomeDashboard.selectedVersion</code> zeigt die verwendete Version, <code>esphome.0._ESPHomeDashboard.newestVersion</code> die neueste bei GitHub.</p><h3 id="was-bedeutet-„always-last-available" tabindex="-1">Was bedeutet „Always last available“? <a class="header-anchor" href="#was-bedeutet-„always-last-available" aria-label="Permalink to &quot;Was bedeutet „Always last available“?&quot;">​</a></h3><p>Damit installiert der Adapter bei jedem Start die neueste ESPHome-Version. Erscheint ein Release, das sich nicht installieren lässt, startet das Dashboard ohne dein Zutun nicht mehr. Wähle deshalb eine feste Version und stell sie zum Aktualisieren gezielt um.</p><h3 id="was-steht-unter-„fortschrittlich" tabindex="-1">Was steht unter „Fortschrittlich“? <a class="header-anchor" href="#was-steht-unter-„fortschrittlich" aria-label="Permalink to &quot;Was steht unter „Fortschrittlich“?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feld</th><th>Standard</th><th>Wofür</th></tr></thead><tbody><tr><td>„Pillow-Version“</td><td><code>Auto Detect</code></td><td>ESPHome installiert die passende Version selbst. Eine feste Version nur, wenn pip im Log genau diese verlangt.</td></tr><tr><td>„ESPHome Device Builder-Version“</td><td><code>Auto Detect</code></td><td>neueste Version, die zur gewählten ESPHome-Version passt</td></tr><tr><td>„Python-Version“</td><td><code>3.13.2</code></td><td>eine Version wie <code>3.13.2</code> oder ein Bereich wie <code>3.12</code>. Eine Änderung legt die Python-Umgebung beim nächsten Start neu an.</td></tr></tbody></table><p>Mit „Docker-Integration verwenden (Beta)“ fallen diese drei Felder weg. Der Adapter startet dann das offizielle ESPHome-Image in der gewählten Version.</p><p>Meldet das Dashboard selbst ein Update, betrifft das nur seine Anzeige. Welche Version läuft, bestimmt allein die Einstellung im Adapter.</p><p><strong>Siehe auch:</strong> <a href="./../fehlerbehebung/dashboard-startet-nicht#dashboard-not-start-pillow-esphome">Warum startet das Dashboard nicht?</a></p><p><a id="use-external-esphome-dashboard-instead"></a></p><h2 id="wie-nutze-ich-ein-externes-esphome-dashboard-statt-des-integrierten" tabindex="-1">Wie nutze ich ein externes ESPHome-Dashboard statt des integrierten? <a class="header-anchor" href="#wie-nutze-ich-ein-externes-esphome-dashboard-statt-des-integrierten" aria-label="Permalink to &quot;Wie nutze ich ein externes ESPHome-Dashboard statt des integrierten?&quot;">​</a></h2><p>Das integrierte Dashboard ist freiwillig. Für die Geräte braucht der Adapter nur deren Adresse und Schlüssel. Wo du die YAML-Dateien bearbeitest und flashst, ist ihm egal.</p><ol><li>Lass im Reiter „ESPHome-Dashboard“ „ESPHome-Dashboard aktivieren“ aus.</li><li>Betreib ESPHome auf einem anderen Rechner, z. B. als Docker-Container oder Home-Assistant-Add-on.</li><li>Füg die Geräte im Reiter „Geräte“ mit Adresse und Schlüssel hinzu.</li><li>Soll der Admin-Tab „ESPHome“ das externe Dashboard zeigen, trag im Reiter „ESPHome-Dashboard“ dessen Adresse in „IP-Adresse, unter der ESPHome Dashboard zur Integration in ioBroker Admin ausgeführt wird“ ein und unter „Fortschrittlich“ den Port.</li></ol><p>Derzeit zeigt der Tab mit Admin 8.0.12 oder neuer bei ausgeschaltetem integriertem Dashboard trotzdem nur den Hinweis, dass es nicht aktiviert ist. Bis das behoben ist, öffnest du das externe Dashboard direkt im Browser, z. B. unter <code>http://&lt;Rechner&gt;:6052</code>.</p><p>Willst du ESPHome in Docker, aber ohne eigenen Aufwand, nimm „Docker-Integration verwenden (Beta)“. Dann startet der Adapter das offizielle ESPHome-Image selbst. Die Option siehst du nur im Expertenmodus des Admins.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/voraussetzungen#systems-hardware-adapter-run">Auf welchen Systemen läuft das Dashboard?</a></p><p><a id="show-dashboard-admin-tab-using"></a></p><h2 id="wie-zeige-ich-das-dashboard-im-admin-tab-bei-https-an" tabindex="-1">Wie zeige ich das Dashboard im Admin-Tab bei HTTPS an? <a class="header-anchor" href="#wie-zeige-ich-das-dashboard-im-admin-tab-bei-https-an" aria-label="Permalink to &quot;Wie zeige ich das Dashboard im Admin-Tab bei HTTPS an?&quot;">​</a></h2><p>Läuft der Admin über HTTPS, blockiert der Browser ein Dashboard, das über HTTP kommt. Du leitest das Dashboard deshalb über den Web- und den Proxy-Adapter, die beide HTTPS können.</p><ol><li>Richte den Web-Adapter mit HTTPS ein.</li><li>Installiere den Proxy-Adapter und leg dort einen Pfad an: Kontext <code>esphome/</code>, Ziel <code>http://localhost:6052</code>.</li><li>Öffne beim ESPHome-Adapter den Reiter „ESPHome-Dashboard“, Bereich „Fortschrittlich“.</li><li>Trag in „URL des ESPHome-Dashboards“ die Adresse über den Proxy ein: <code>https://&lt;ioBroker-IP&gt;:&lt;Web-Port&gt;/proxy.0/esphome/</code>. Der Web-Port ist meist 8082.</li><li>Speichere und öffne den Tab „ESPHome“.</li></ol><p>Änderst du danach die IP-Adresse oder den Port des Dashboards, setzt der Adapter das URL-Feld auf <code>http://&lt;IP&gt;:&lt;Port&gt;</code> zurück. Trag die Proxy-Adresse dann erneut ein.</p><p>Für eine Anmeldung am Dashboard setzt du unter „Fortschrittlich“ „Benutzername des ESPHome-Dashboards“ und „Passwort des ESPHome-Dashboards“, beide oder keins. Sie gelten ab dem nächsten Start des Dashboards.</p>',28)])])}const m=t(s,[["render",d]]);export{c as __pageData,m as default};
